# Improved cleaning: handle source 2 and source 3 better
def clean_title_v2(title, source_id, artist, album):
    if pd.isna(title):
        return ''
    t = str(title).strip()
    # Source 4: remove leading "00X-" prefix
    if source_id == 4:
        t = re.sub(r'^\d{3}-', '', t)
    # Source 2: remove "Artist - " prefix
    if source_id == 2 and pd.notna(artist):
        prefix = f"{str(artist).strip()} - "
        if t.startswith(prefix):
            t = t[len(prefix):]
        elif ' - ' in t:
            # if artist NaN, take after first ' - '
            pass
    # Source 2 with artist NaN: split on ' - '
    if source_id == 2 and (pd.isna(artist) or artist == ''):
        if ' - ' in t:
            t = t.split(' - ', 1)[1]
    # Source 1: remove trailing " (Album)"
    if source_id == 1 and pd.notna(album):
        suffix = f" ({str(album).strip()})"
        if t.endswith(suffix):
            t = t[:-len(suffix)]
    # Source 3: remove trailing " - <something>"
    if source_id == 3:
        if ' - ' in t:
            t = t.rsplit(' - ', 1)[0]
    return t.strip()

def clean_artist_v2(artist, title, source_id):
    if pd.notna(artist) and str(artist).strip() != '':
        return str(artist).strip()
    # Source 2: artist in title prefix
    if source_id == 2 and pd.notna(title) and ' - ' in str(title):
        return str(title).split(' - ', 1)[0].strip()
    return ''

def clean_album_v2(album, source_id, title):
    if pd.notna(album) and str(album).strip() != '':
        a = str(album).strip()
        if source_id == 4:
            a = re.sub(r'\s*\(\d{2,4}\)\s*$', '', a).strip()
            a = re.sub(r'\s*\(unknown\)\s*$', '', a).strip()
        return a
    # Source 3 with album NaN: title is "Title - Album"
    if source_id == 3 and pd.notna(title) and ' - ' in str(title):
        return str(title).rsplit(' - ', 1)[1].strip()
    return ''

tracks['title_c'] = tracks.apply(lambda r: clean_title_v2(r['title'], r['source_id'], r['artist'], r['album']), axis=1)
tracks['artist_c'] = tracks.apply(lambda r: clean_artist_v2(r['artist'], r['title'], r['source_id']), axis=1)
tracks['album_c'] = tracks.apply(lambda r: clean_album_v2(r['album'], r['source_id'], r['title']), axis=1)

